// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);

        vm.deal(alice, 10 ether);
        vm.deal(bob, 10 ether);

        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        vm.prank(bob);
        c.addToBalance{value: 2 ether}();

        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        bool ok;
        vm.prank(alice);
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.getBalance(alice) == 0, "Alice balance should be 0 in reference");
    }
}
